function ImagePicker({images,onChange,single=false}){const r=useRemote('/admin/media'),[open,setOpen]=useState(false),[search,setSearch]=useState('');return <div className="image-picker"><div className="chosen-images">{images.map((i,n)=><div key={i.url}><Image src={i.url} alt={i.alt}/><button type="button" aria-label="Elimină imaginea" onClick={()=>onChange(images.filter((_,x)=>x!==n))}>×</button><input aria-label="Text alternativ imagine" value={i.alt} onChange={e=>onChange(images.map((x,k)=>k===n?{...x,alt:e.target.value}:x))}/>{n>0&&<button type="button" className="image-first" onClick={()=>onChange([i,...images.filter((_,k)=>k!==n)])}>Imagine principală</button>}</div>)}</div><button className="admin-button" type="button" onClick={()=>setOpen(!open)}><ImageIcon size={17}/>Alege din bibliotecă</button>{open&&<div className="picker-library"><input placeholder="Caută o imagine…" aria-label="Caută imagine" value={search} onChange={e=>setSearch(e.target.value)}/><div>{r.data?.filter(m=>(m.name+' '+m.alt).toLowerCase().includes(search.toLowerCase())).map(m=><button type="button" key={m.id} onClick={()=>{const image={url:m.url,alt:m.alt};onChange(single?[image]:images.some(x=>x.url===m.url)?images:[...images,image]);setOpen(false);}}><Image src={m.url} alt={m.alt}/><small>{m.name}</small></button>)}</div></div>}</div>;}
