function SettingsPage({initial='general'}){const s=useStore(),[version,setVersion]=useState(0),r=useRemote('/admin/settings',version),[tab,setTab]=useState(initial),[v,setV]=useState(null),[editing,setEditing]=useState(null),[busy,setBusy]=useState(false);useEffect(()=>{if(r.data)setV(r.data.settings);},[r.data]);if(!v)return <div className="loading">{r.error||'Se încarcă…'}</div>;const set=(k,x)=>setV(p=>({...p,[k]:x})),fields=(keys)=>keys.map(([k,l,type])=><Field key={k} label={l} type={type||'text'} value={v[k]} onChange={x=>set(k,x)} wide={type==='textarea'}/>);return <><PageHead title="Setările magazinului" text="Identitate, SEO, livrare și plăți."/><nav className="period-tabs">{[['general','General'],['seo','SEO'],['shipping','Livrare'],['payments','Plăți']].map(([id,l])=><button key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}>{l}</button>)}</nav>{['general','seo'].includes(tab)?<form className="admin-card settings-form" onSubmit={async e=>{e.preventDefault();setBusy(true);try{const allowed=['seo_title','seo_description','seo_og_image','store_name','phone','email','address','low_stock_threshold'];await api('/admin/settings',{method:'PUT',body:Object.fromEntries(allowed.filter(k=>k in v).map(k=>[k,v[k]]))});await s.refresh();s.notify('Setările au fost salvate.');}catch(e){s.notify(e.message,'error');}finally{setBusy(false);}}}><div className="admin-form-grid">{tab==='seo'?fields([['seo_title','Titlu implicit site'],['seo_description','Descriere implicită','textarea'],['seo_og_image','Imagine OG (URL local)']]):fields([['store_name','Nume magazin'],['phone','Telefon'],['email','Email'],['address','Adresă'],['low_stock_threshold','Prag stoc redus','number']])}</div><div className="editor-footer"><button className="admin-button primary" disabled={busy}><Save size={17}/>Salvează setările</button></div></form>:tab==='shipping'?<section className="admin-card"><div className="admin-card-head"><h2>Metode de livrare</h2><button className="admin-button primary" onClick={()=>setEditing({})}><Plus size={16}/>Metodă nouă</button></div><div className="table-wrap"><table><thead><tr><th>Metodă</th><th>Cost</th><th>Gratuit de la</th><th>Zone</th><th>Status</th><th>Acțiuni</th></tr></thead><tbody>{r.data.shipping.map(m=><tr key={m.id}><td>{m.name}</td><td>{money(m.price_cents)}</td><td>{m.free_threshold_cents===null?'—':money(m.free_threshold_cents)}</td><td>{m.zones||'Toate'}</td><td>{m.enabled?'Activ':'Inactiv'}</td><td><button className="admin-button" onClick={()=>setEditing(m)}>Editează</button></td></tr>)}</tbody></table></div></section>:tab==='payments'?<section className="admin-card"><h2>Metode de plată</h2>{r.data.payments.map(p=><div className="payment-row" key={p.code}><div><h3>{p.name}</h3><p>{p.code==='card'?'Stripe Checkout · modul test. Confirmarea plății este verificată pe server.':'Disponibil în checkout dacă este activ.'}</p></div><button className={'admin-button '+(p.enabled?'primary':'')} disabled={p.code==='card'&&!s.data.stripe?.configured} onClick={async()=>{try{await api('/admin/payments/'+p.code,{method:'PUT',body:{enabled:p.enabled?0:1}});setVersion(v=>v+1);s.refresh();}catch(e){s.notify(e.message,'error');}}}>{p.enabled?'Activ':'Inactiv'}</button></div>)}<StripePanel/></section>:null}<Dialog open={!!editing} onClose={()=>setEditing(null)} className="admin-editor-dialog" label="Metodă livrare">{editing&&<EntityForm key={editing.id||'new'} entity="shipping" record={editing} onClose={()=>setEditing(null)} onSaved={()=>{setVersion(v=>v+1);s.refresh();}}/>}</Dialog></>;}
function Communication({type}){const s=useStore(),[version,setVersion]=useState(0),[q,setQ]=useState(''),[selected,setSelected]=useState(null),r=useRemote('/admin/'+type,version),rows=r.data?.filter(x=>JSON.stringify(x).toLowerCase().includes(q.toLowerCase())),title={newsletter:'Newsletter',messages:'Mesaje și cereri',reviews:'Recenzii',outbox:'Email local'}[type];return <><PageHead title={title} text={type==='outbox'?'Mesajele sunt generate local; nu sunt trimise prin SMTP.':undefined} extra={type==='newsletter'?<a className="admin-button" href="/api/admin/export/newsletter">Export CSV</a>:null}/><section className="admin-card"><div className="admin-search"><Search size={17}/><input aria-label="Caută în mesaje" placeholder="Caută…" value={q} onChange={e=>setQ(e.target.value)}/></div><div className="table-wrap"><table><thead><tr><th>{type==='newsletter'?'Email':type==='outbox'?'Destinatar':'Nume'}</th><th>{type==='newsletter'?'Consimțământ':type==='reviews'?'Evaluare':'Subiect / mesaj'}</th><th>{type==='messages'?'Status':'Data'}</th><th>Acțiune</th></tr></thead><tbody>{rows?.map(x=><tr key={x.id}><td>{x.name||x.email||x.recipient}{x.name&&<small>{x.email}</small>}</td><td>{type==='newsletter'?date(x.consent_at):type==='reviews'?x.rating+' / 5':x.subject||x.body.slice(0,70)}</td><td>{type==='messages'?<Badge status={x.status}/>:type==='newsletter'?'Abonat':date(x.created_at)}</td><td>{type!=='newsletter'&&<button className="admin-button" onClick={()=>setSelected(x)}>Detalii</button>}{type==='reviews'&&<button className="admin-button" onClick={async()=>{try{await api('/admin/reviews/'+x.id,{method:'PATCH',body:{approved:x.approved?0:1}});setVersion(v=>v+1);s.refresh();}catch(e){s.notify(e.message,'error');}}}>{x.approved?'Retrage':'Aprobă'}</button>}</td></tr>)}</tbody></table></div>{rows?.length===0&&<Empty icon={Mail} title="Nu există înregistrări." link={null}/>}</section><Dialog open={!!selected} onClose={()=>setSelected(null)} className="admin-editor-dialog" label="Detalii mesaj">{selected&&<><h2>{selected.subject||selected.name}</h2><p>{selected.email||selected.recipient} · {selected.phone}</p><p className="message-body">{selected.body}</p>{type==='reviews'&&<><Field label="Răspuns Floralis" type="textarea" value={selected.reply||''} onChange={reply=>setSelected({...selected,reply})}/><div className="editor-footer"><button className="admin-button primary" onClick={async()=>{await api('/admin/reviews/'+selected.id,{method:'PATCH',body:{approved:selected.approved,reply:selected.reply||''}});setVersion(v=>v+1);setSelected(null);s.refresh();}}>Salvează răspunsul</button></div></>}{type==='messages'&&<div className="editor-footer">{[['read','Marchează citit'],['resolved','Rezolvat']].map(([status,l])=><button key={status} className="admin-button primary" onClick={async()=>{await api('/admin/messages/'+selected.id,{method:'PATCH',body:{status}});setVersion(v=>v+1);setSelected(null);}}>{l}</button>)}</div>}</>}</Dialog></>;}
function FullEditor({kind,id}){const s=useStore(),navigate=useNavigate(),entity={produse:'products',categorii:'categories',articole:'pages'}[kind],list=entity==='products'?'/admin/products/'+id:'/admin/'+entity,r=useRemote(id?list:'/admin/'+entity),record=id?(entity==='products'?r.data:r.data?.find(x=>x.id===Number(id)&&(kind!=='articole'||x.type==='post'))):(kind==='articole'?{type:'post'}:{});if(id&&!r.data)return <div className="loading">{r.error||'Se încarcă…'}</div>;if(id&&!record)return <Empty title="Înregistrarea nu a fost găsită." link={'/admin/'+kind}/>;const back=()=>navigate('/admin/'+kind);return <><PageHead title={id?'Editează':'Înregistrare nouă'} extra={<button className="admin-button" onClick={back}>Înapoi la listă</button>}/><div className="admin-card admin-editor-dialog admin-full-editor"><EntityForm key={id||'new'} entity={entity} record={record} onClose={back} onSaved={()=>s.refresh()}/></div></>;}
function EmailPage(){const s=useStore(),r=useRemote('/admin/email/settings'),[tab,setTab]=useState('config'),[v,setV]=useState(null),[busy,setBusy]=useState(false),[recipient,setRecipient]=useState('');useEffect(()=>{if(r.data)setV({...r.data,password:''});},[r.data]);if(!v)return <div className="loading">{r.error||'Se încarcă…'}</div>;return <><PageHead title="Configurare email" text="Expeditor, SMTP și mesajele magazinului."/><nav className="period-tabs"><button className={tab==='config'?'active':''} onClick={()=>setTab('config')}>Configurare</button><button className={tab==='outbox'?'active':''} onClick={()=>setTab('outbox')}>Mesaje generate</button></nav>{tab==='outbox'?<Communication type="outbox"/>:<><form className="admin-card settings-form" onSubmit={async e=>{e.preventDefault();setBusy(true);try{await api('/admin/email/settings',{method:'PUT',body:v});s.notify('Configurarea email a fost salvată.');}catch(e){s.notify(e.message,'error');}finally{setBusy(false);}}}><div className="admin-form-grid">{[['from_name','Nume expeditor'],['from_email','Email expeditor','email'],['host','Server SMTP'],['port','Port SMTP','number'],['username','Utilizator SMTP'],['password',v.password_set?'Parolă SMTP (gol = păstrează)':'Parolă SMTP','password']].map(([k,l,type])=><Field key={k} label={l} value={v[k]} type={type||'text'} onChange={x=>setV({...v,[k]:x})}/>)}<Field label="Securitate" type="select" value={v.security} onChange={x=>setV({...v,security:x})} options={[["starttls","STARTTLS"],["ssl","SSL / TLS"]]}/><Field label="Trimitere SMTP activă" type="checkbox" value={v.enabled} onChange={x=>setV({...v,enabled:x})}/></div><p className="admin-note">Cu SMTP dezactivat, mesajele și linkurile de resetare rămân în outbox. Pentru trimitere automată, configurează sarcina PHP send-outbox din README.</p><div className="editor-footer"><button className="admin-button primary" disabled={busy}>Salvează configurarea</button></div></form><form className="admin-card" onSubmit={async e=>{e.preventDefault();setBusy(true);try{await api('/admin/email/test',{method:'POST',body:{email:recipient}});s.notify('Mesajul de test a fost trimis.');}catch(e){s.notify(e.message,'error');}finally{setBusy(false);}}}><h2>Testează trimiterea</h2><div className="admin-toolbar"><input type="email" required aria-label="Destinatar test email" value={recipient} onChange={e=>setRecipient(e.target.value)} placeholder="Email destinatar"/><button className="admin-button" disabled={busy||!v.enabled}>Trimite email de test</button></div></form></>}</>;}
function Login(){const s=useStore(),navigate=useNavigate(),[error,setError]=useState(''),[busy,setBusy]=useState(false);return <div className="admin-login"><Link to="/"><Logo/></Link><span className="eyebrow">ADMINISTRARE MAGAZIN</span><h1>Bine ai venit în atelier.</h1><form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{await api('/auth/login',{method:'POST',body:{...Object.fromEntries(new FormData(e.currentTarget)),admin:true}});await s.refresh();navigate('/admin');}catch(e){setError(e.message);}finally{setBusy(false);}}}><label>Email<input name="email" type="email" required autoComplete="username"/></label><label>Parolă<input name="password" type="password" required autoComplete="current-password"/></label>{error&&<p className="form-error" role="alert">{error}</p>}<button className="admin-button primary" disabled={busy}>{busy?'Se verifică…':'Intră în atelier'}</button></form><Link className="text-link" to="/">Înapoi la magazin</Link></div>;}
export default function Admin(){const s=useStore(),loc=useLocation(),navigate=useNavigate(),[open,setOpen]=useState(false),[collapsed,setCollapsed]=useState(()=>localStorage.getItem('floralis-admin-collapsed')==='1'),key=loc.pathname.slice('/admin'.length).replace(/^\//,''),module=modules.find(m=>m[0]===key.split('/')[0])||modules[0];useEffect(()=>{setOpen(false);if(s.data&&s.data.user?.role!=='admin'&&key!=='login')navigate('/admin/login',{replace:true});},[loc.pathname,s.data?.user]);if(!s.data)return <div className="loading">Se încarcă atelierul…</div>;if(s.data.user?.role!=='admin'||key==='login')return <Login/>;const editorMatch=key.match(/^(produse|categorii|articole)\/(?:creare|(\d+)\/editare)$/),orderMatch=key.match(/^comenzi\/(\d+)$/);const body=editorMatch?<FullEditor kind={editorMatch[1]} id={editorMatch[2]}/>:orderMatch?<div className="admin-card admin-editor-dialog admin-full-editor"><OrderEditor id={orderMatch[1]} onSaved={()=>navigate('/admin/comenzi')}/></div>:key===''?<Dashboard/>:key==='produse'?<Catalog kind="products"/>:key==='categorii'?<Catalog kind="categories"/>:key==='comenzi'?<Orders/>:key==='clienti'?<Customers/>:key==='stoc'?<Stock/>:key==='cupoane'?<ContentList discounts/>:key==='articole'?<ContentList posts/>:key==='media'?<Media/>:key==='setari'?<SettingsPage/>:key==='newsletter'?<Communication type="newsletter"/>:key==='mesaje'?<Communication type="messages"/>:key==='recenzii'?<Communication type="reviews"/>:key==='email'||key==='setari/email'?<EmailPage/>:key==='seo'?<SettingsPage initial="seo"/>:key==='plati'?<SettingsPage initial="payments"/>:key==='livrare'?<SettingsPage initial="shipping"/>:<Empty title="Modul inexistent." link="/admin" label="Dashboard"/>;return <div className={'admin-app admin-body '+(collapsed?'collapsed ':'')+(open?'menu-open':'')}><aside className="admin-sidebar"><Link to="/admin" className="admin-logo"><Logo/><span>ADMINISTRARE MAGAZIN</span></Link><button className="sidebar-collapse icon" aria-label="Restrânge meniul" onClick={()=>{localStorage.setItem('floralis-admin-collapsed',collapsed?'0':'1');setCollapsed(!collapsed);}}><PanelLeftClose/></button><nav>{modules.map(([id,label,sub,Icon,group])=><React.Fragment key={id}>{group&&<small>{group}</small>}<NavLink to={'/admin'+(id?'/'+id:'')} end={id===''||id==='setari'} title={label}><Icon size={19}/><span><strong>{label}</strong><em>{sub}</em></span></NavLink></React.Fragment>)}</nav><div className="admin-user"><span>AF</span><div><b>{s.data.user.name}</b><small>{s.data.user.email}</small></div><button className="icon" aria-label="Ieșire din admin" onClick={async()=>{await api('/auth/logout',{method:'POST'});await s.refresh();navigate('/admin/login');}}><LogOut/></button></div></aside>{open&&<button className="admin-backdrop" aria-label="Închide meniul" onClick={()=>setOpen(false)}/>}<div className="admin-shell"><header className="admin-topbar"><button className="icon admin-menu-toggle" onClick={()=>setOpen(!open)} aria-label="Deschide meniul admin"><Menu/></button><div className="admin-crumb"><small>FLORALIS / ADMIN / {module[1].toUpperCase()}</small><strong>{module[1]}</strong></div><nav><Link className="admin-button" to="/admin/produse"><Plus size={15}/><span>Produse</span></Link><Link className="admin-button" to="/"><ExternalLink size={15}/><span>Vezi magazinul</span></Link><span className="admin-avatar">AF</span></nav></header><main className="admin-main" key={key}>{body}</main></div></div>;}
